import {
    useEffect,
    useState,
} from "react";

const MOVESET_PATH = "/csv_movesets/";

export default function PokemonBuildPanel({
    clickedBuild,
    selectedGen,
}) {
    const [movesetFiles, setMovesetFiles] =
        useState([]);
    const [buildData, setBuildData] =
        useState(null);

    const normalize = (str) =>
        str?.toLowerCase().replace(/[^a-z0-9]/g, "") ||
        "";

    const loadCSV = async (path) => {
        const res = await fetch(path);
        return await res.text();
    };

    const parseCSV = (text) =>
        text
            .trim()
            .split("\n")
            .slice(1)
            .map((r) =>
                r.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/)
            );

    useEffect(() => {
        fetch(MOVESET_PATH + "files.json")
            .then((res) => res.json())
            .then((data) =>
                setMovesetFiles(data.files)
            );
    }, []);

    useEffect(() => {
        if (!clickedBuild) {
            setBuildData(null);
            return;
        }

        const loadBuild = async () => {
            const targetFile =
                movesetFiles.find((f) =>
                    f.includes(
                        `${clickedBuild.month}_gen${selectedGen}`
                    )
                );

            if (!targetFile) {
                setBuildData(null);
                return;
            }

            const text = await loadCSV(
                MOVESET_PATH + targetFile
            );

            const rows = parseCSV(text);

            const pokemonRows = rows.filter(
                (r) =>
                    normalize(r[1]) ===
                    normalize(clickedBuild.pokemon)
            );

            const grouped = {};

            for (let row of pokemonRows) {
                const category = row[2];
                const itemName = row[4];
                const usage = row[5];

                if (!grouped[category]) {
                    grouped[category] = [];
                }

                grouped[category].push({
                    name: itemName,
                    usage,
                });
            }

            setBuildData({
                pokemon: clickedBuild.pokemon,
                month: clickedBuild.month,
                data: grouped,
            });
        };

        loadBuild();
    }, [
        clickedBuild,
        movesetFiles,
        selectedGen,
    ]);

    if (!buildData) return null;

    return (
        <div
            style={{
                marginBottom: "20px",
                padding: "15px",
                background: "#f8f8f8",
                border: "1px solid #ddd",
                borderRadius: "10px",
            }}
        >
            <h3>
                {buildData.pokemon} —{" "}
                {buildData.month}
            </h3>

            {Object.entries(buildData.data).map(
                ([category, items]) => (
                    <div key={category}>
                        <strong>{category}</strong>
                        <ul>
                            {items.map((item, idx) => (
                                <li key={idx}>
                                    {item.name} (
                                    {item.usage}%)
                                </li>
                            ))}
                        </ul>
                    </div>
                )
            )}
        </div>
    );
}
